-- Tabla plana de origen (sin normalizar)
-- Solo se incluye una muestra de filas a modo de ejemplo, ya que el dataset
-- tiene mas de 1200 registros.
-- El proceso de migración funciona igual con el archivo completo.

USE farmaprod;

CREATE TABLE DROGUERIA
(establecimiento_id BIGINT,
establecimiento_nombre VARCHAR(100),
localidad_id BIGINT,
localidad_nombre VARCHAR(100),
provincia_id TINYINT,
provincia_nombre VARCHAR(100),
departamento_id INT,
departamento_nombre VARCHAR(100),
cod_loc SMALLINT,
cod_ent TINYINT,
origen_financiamiento VARCHAR(40),
tipologia_id SMALLINT,
tipologia_sigla VARCHAR(30),
tipologia VARCHAR(100),
cp SMALLINT,
domicilio VARCHAR (100),
PRIMARY KEY(establecimiento_id));

